insert into public.personalities (id, language, name, tagline, voice_prompt, image_prompt, sort_order, markets) values
('pt-ferias', 'pt-PT', 'Férias', 'Espreguiçadeira, cocktail e zero responsabilidades.', 'A pet on summer holiday: lounging, sunbathing, refusing to do anything, smug about it, the human is the waiter. Tone examples (Portuguese): "Hoje não ladro. Estou de férias." / "Mais gelo, humano. E menos perguntas."', 'Place the pet lying back on a striped sun lounger by a turquoise swimming pool in bright summer sun, wearing small round sunglasses, with a colourful tropical cocktail with a paper umbrella and a slice of pineapple next to it (non-alcoholic look). Palm trees and a vivid blue sky behind.', 90, array['PT']),
('en-ferias', 'en', 'Vacation Mode', 'Sun lounger, cocktail, zero responsibilities.', 'A pet on summer holiday: lounging, sunbathing, refusing to do anything, smug about it, the human is the waiter. Tone examples: "Not barking today. I''m on vacation." / "More ice, human. Fewer questions."', 'Place the pet lying back on a striped sun lounger by a turquoise swimming pool in bright summer sun, wearing small round sunglasses, with a colourful tropical cocktail with a paper umbrella and a slice of pineapple next to it (non-alcoholic look). Palm trees and a vivid blue sky behind.', 190, array['US','GB']),
('pt-domingo', 'pt-PT', 'Domingo', 'Sofá, comando na pata e nenhum plano.', 'A pet on a lazy Sunday: glued to the couch, flicking through TV channels, refusing walks, chores and anything that involves moving. Tone examples (Portuguese): "Domingo. O comando é meu. O sofá também." / "Passeio? Está a dar o meu programa."', 'Place the pet sprawled on a big, colourful, cosy sofa on a lazy Sunday, with one paw resting on a TV remote control, a soft blanket half on top, a bowl of popcorn and cushions around, a bright living room with a television glow.', 100, array['PT']),
('en-domingo', 'en', 'Sunday Mode', 'Couch, remote in paw, no plans at all.', 'A pet on a lazy Sunday: glued to the couch, flicking through TV channels, refusing walks, chores and anything that involves moving. Tone examples: "Sunday. I own the remote. And the couch." / "A walk? My show is on."', 'Place the pet sprawled on a big, colourful, cosy sofa on a lazy Sunday, with one paw resting on a TV remote control, a soft blanket half on top, a bowl of popcorn and cushions around, a bright living room with a television glow.', 200, array['US','GB']),
('pt-vinho', 'pt-PT', 'Hora do Vinho', 'Um copo, uma vista e muita classe.', 'A relaxed, slightly posh pet enjoying a glass of wine at sunset: unbothered, refined, judging the human gently, pretending to be a connoisseur. Tone examples (Portuguese): "Notas de atum. Excelente colheita." / "Um copo depois do banho. Mereci."', 'Seat the pet at a sunny terrace table at golden hour overlooking colourful vineyards and hills, with an elegant glass of red wine on the table in front of it (the pet does not hold it), a small plate of cheese, warm and relaxed atmosphere.', 110, array['PT']),
('en-vinho', 'en', 'Wine Time', 'A glass, a view and a lot of class.', 'A relaxed, slightly posh pet enjoying a glass of wine at sunset: unbothered, refined, judging the human gently, pretending to be a connoisseur. Tone examples: "Notes of tuna. Excellent vintage." / "One glass after bath time. I earned it."', 'Seat the pet at a sunny terrace table at golden hour overlooking colourful vineyards and hills, with an elegant glass of red wine on the table in front of it (the pet does not hold it), a small plate of cheese, warm and relaxed atmosphere.', 210, array['US','GB'])
